import type { CommandModel, Described, DomainModel, ElementModel, FieldModel, InvariantModel, PrimitiveName, TypeExpr } from '../model/model.js';
import { elementsIn } from '../model/model.js';
import {
    EVENT_TAG,
    STATE_TAG,
    aggregateParamName,
    commandTypeName,
    commandsInterfaceName,
    commonTypeName,
    invalidTypeName,
    makeTypeName,
    stateTypeName,
} from './naming.js';

export interface GeneratedFile {
    /** Path relative to the output directory. */
    path: string;
    content: string;
}

/** First line of every generated file; also how the generator recognizes files it may replace. */
export const GENERATED_MARKER = '// Generated by domaintrail.';
const HEADER = '// Generated by domaintrail. DO NOT EDIT — change the .dt sources and run `dmtr generate ts`.\n';

const PRIMITIVES: Record<PrimitiveName, string> = {
    String: 'string',
    Int: 'number',
    Decimal: 'Decimal',
    Bool: 'boolean',
    Timestamp: 'Timestamp',
    UUID: 'string',
};

const RUNTIME = `${HEADER}
/** Result of a command: either a success value or a domain error. */
export type Result<T, E> = Ok<T> | Err<E>;
export interface Ok<T> {
    readonly ok: true;
    readonly value: T;
}
export interface Err<E> {
    readonly ok: false;
    readonly error: E;
}

export const ok = <T>(value: T): Ok<T> => ({ ok: true, value });
export const err = <E>(error: E): Err<E> => ({ ok: false, error });

/** Decimal values are carried as strings so that no precision is lost. */
export type Decimal = string & { readonly __brand: 'Decimal' };

/** Point in time. */
export type Timestamp = Date;
`;

/** Generates one module per bounded context plus a shared runtime and an index. Requires a model without errors. */
export function generateTypeScript(model: DomainModel): GeneratedFile[] {
    const files: GeneratedFile[] = [{ path: '_runtime.ts', content: RUNTIME }];
    for (const ctx of model.contexts) {
        files.push({ path: `${ctx}.ts`, content: new ContextEmitter(model, ctx).emit() });
    }
    const index = [
        HEADER,
        `export * from './_runtime.js';`,
        ...model.contexts.map((c) => `export * as ${c} from './${c}.js';`),
        '',
    ].join('\n');
    files.push({ path: 'index.ts', content: index });
    return files;
}

/** Text that is safe inside a block comment. */
const comment = (s: string): string => s.replace(/\*\//g, '* /');

/** Japanese name and description lines of a declaration. */
const describedLines = (d: Described): string[] => [d.label, d.doc].filter((x): x is string => !!x);

const invariantLines = (invs: InvariantModel[]): string[] =>
    invs.map((i) => `@invariant ${i.name}${i.label ? ` (${i.label})` : ''}: ${i.source}`);

class ContextEmitter {
    private readonly imports = new Set<string>();
    private readonly out: string[] = [];

    constructor(
        private readonly model: DomainModel,
        private readonly ctx: string,
    ) {}

    emit(): string {
        for (const el of elementsIn(this.model, this.ctx)) {
            switch (el.kind) {
                case 'id':
                case 'primitive':
                    this.primitive(el);
                    break;
                case 'enum':
                    this.jsdoc(describedLines(el));
                    if (!el.values?.length) {
                        this.line(`export type ${el.name} = never;`);
                    } else if (el.valueLabels) {
                        this.line(`export type ${el.name} =`);
                        el.values.forEach((v, i) => {
                            const label = el.valueLabels?.[v];
                            this.line(`    | '${v}'${i === el.values!.length - 1 ? ';' : ''}${label ? ` // ${label}` : ''}`);
                        });
                    } else {
                        this.line(`export type ${el.name} = ${el.values.map((v) => `'${v}'`).join(' | ')};`);
                    }
                    break;
                case 'valueObject':
                case 'entity':
                    this.jsdoc([...describedLines(el), ...invariantLines(el.invariants)]);
                    this.iface(el.name, undefined, [], el.fields);
                    break;
                case 'event':
                case 'error':
                    this.jsdoc(describedLines(el));
                    this.iface(el.name, undefined, [`readonly ${EVENT_TAG}: '${el.name}';`], el.fields);
                    break;
                case 'aggregate':
                    this.aggregate(el);
                    break;
            }
            this.out.push('');
        }
        const body = this.out.join('\n');
        const runtime = ['Decimal', 'Result', 'Timestamp'].filter((n) => new RegExp(`\\b${n}\\b`).test(body));
        const imports = [
            ...(runtime.length ? [`import type { ${runtime.join(', ')} } from './_runtime.js';`] : []),
            ...[...this.imports].sort().map((c) => `import type * as ${c} from './${c}.js';`),
        ];
        return [HEADER, ...imports, '', body].join('\n');
    }

    /**
     * Domain primitive (or ID): a branded type, the error for invalid values, and the constructor contract.
     * The constructor is implemented by hand; invariants are documented, not checked at run time.
     */
    private primitive(p: ElementModel): void {
        const base = PRIMITIVES[p.base ?? 'String'];
        const summary = p.kind === 'id' && !p.label ? [`Identifier of ${p.name}.`] : [];
        this.jsdoc([...describedLines(p), ...summary, ...invariantLines(p.invariants)]);
        this.line(`export type ${p.name} = ${base} & { readonly __domain: '${p.id}' };`);
        this.out.push('');
        if (p.invariants.length === 0) {
            this.jsdoc([`Creates a ${p.name}. It has no invariants, so creation cannot fail.`]);
            this.line(`export type ${makeTypeName(p)} = (value: ${base}) => ${p.name};`);
            return;
        }
        this.jsdoc([`A value that violates an invariant of ${p.name}.`]);
        this.line(`export interface ${invalidTypeName(p)} {`);
        this.line(`    readonly type: '${invalidTypeName(p)}';`);
        this.line(`    readonly value: ${base};`);
        this.line(`    /** The violated invariant. */`);
        this.line(`    readonly invariant: ${p.invariants.map((i) => `'${i.name}'`).join(' | ')};`);
        this.line('}');
        this.out.push('');
        this.jsdoc([`Creates a ${p.name}, checking its invariants. Implement by hand.`]);
        this.line(`export type ${makeTypeName(p)} = (value: ${base}) => Result<${p.name}, ${invalidTypeName(p)}>;`);
    }

    private aggregate(agg: ElementModel): void {
        const states = agg.states ?? [];
        if (states.length === 0) {
            this.jsdoc([...describedLines(agg), ...invariantLines(agg.invariants)]);
            this.iface(agg.name, undefined, [], agg.fields);
        } else {
            this.jsdoc([`Fields shared by every state of ${agg.label ? `${agg.label} (${agg.name})` : agg.name}.`, ...invariantLines(agg.invariants)]);
            this.iface(commonTypeName(agg), undefined, [], agg.fields);
            for (const s of states) {
                this.out.push('');
                this.jsdoc([...describedLines(s), ...invariantLines(s.invariants)]);
                this.iface(stateTypeName(agg, s), commonTypeName(agg), [`readonly ${STATE_TAG}: '${s.name}';`], s.fields);
            }
            this.out.push('');
            this.jsdoc(describedLines(agg));
            this.line(`export type ${agg.name} = ${states.map((s) => stateTypeName(agg, s)).join(' | ')};`);
        }

        const commands = agg.commands ?? [];
        for (const c of commands) {
            this.out.push('');
            this.command(agg, c);
        }
        if (commands.length > 0) {
            this.out.push('');
            this.jsdoc([`Command contracts of ${agg.name}. Implement this interface by hand.`]);
            this.line(`export interface ${commandsInterfaceName(agg)} {`);
            for (const c of commands) {
                if (c.label) this.line(`    /** ${comment(c.label)} */`);
                this.line(`    readonly ${c.name}: ${commandTypeName(agg, c)};`);
            }
            this.line('}');
        }
    }

    private command(agg: ElementModel, c: CommandModel): void {
        const stateful = (agg.states ?? []).length > 0;
        const stateUnion = (names: string[]): string => (stateful ? names.map((n) => stateTypeName(agg, n)).join(' | ') : agg.name);
        const params: string[] = [];
        if (!c.factory) params.push(`${aggregateParamName(agg)}: ${stateUnion(c.from)}`);
        for (const p of c.params) params.push(`${p.name}: ${this.fieldType(p)}${p.cardinality === 'optional' ? ' | undefined' : ''}`);

        const output = stateUnion(c.to);
        const events = c.emits.length === 0 ? 'never' : c.emits.map((e) => this.ref(e)).join(' | ');
        const eventArray = c.emits.length > 1 ? `readonly (${events})[]` : `readonly ${events}[]`;
        const errors = c.errors.length === 0 ? 'never' : c.errors.map((e) => this.ref(e)).join(' | ');

        const transition = c.factory ? `new -> ${c.to.join(' | ') || agg.name}` : stateful ? `${c.from.join(' | ')} -> ${c.to.join(' | ')}` : '';
        this.jsdoc([
            `${agg.name}.${c.name}${transition ? ` (${transition})` : ''}${c.factory ? ' — factory' : ''}`,
            ...describedLines(c),
            ...c.params.filter((p) => p.label || p.doc).map((p) => `@param ${p.name} ${[p.label, p.doc].filter(Boolean).join(' — ')}`),
        ]);
        this.line(`export type ${commandTypeName(agg, c)} = (`);
        for (const p of params) this.line(`    ${p},`);
        this.line(`) => Result<readonly [${output}, ${eventArray}], ${errors}>;`);
    }

    private iface(name: string, base: string | undefined, extra: string[], fields: FieldModel[]): void {
        const lines = [...extra, ...fields.flatMap((f) => this.property(f))];
        const ext = base ? ` extends ${base}` : '';
        if (lines.length === 0) {
            this.line(`export interface ${name}${ext} {}`);
            return;
        }
        this.line(`export interface ${name}${ext} {`);
        for (const l of lines) this.line(`    ${l}`);
        this.line('}');
    }

    private property(f: FieldModel): string[] {
        const doc = [f.label, f.doc].filter(Boolean).join(' — ');
        const prefix = doc ? [`/** ${comment(doc).replace(/\n/g, ' ')} */`] : [];
        const ref = f.kind === 'references' && f.target ? ` // -> ${f.target}` : '';
        if (f.cardinality === 'optional') return [...prefix, `readonly ${f.name}?: ${this.fieldType(f)};${ref}`];
        return [...prefix, `readonly ${f.name}: ${this.fieldType(f)};${ref}`];
    }

    private fieldType(f: FieldModel): string {
        const t = this.typeExpr(f.type);
        switch (f.cardinality) {
            case 'many':
                return `readonly ${t}[]`;
            case 'nonEmpty':
                return `readonly [${t}, ...${t}[]]`;
            default:
                return t;
        }
    }

    private typeExpr(t: TypeExpr): string {
        return t.kind === 'primitive' ? PRIMITIVES[t.name] : this.ref(t.ref);
    }

    /** TypeScript reference to a qualified element name, importing other contexts as namespaces. */
    private ref(qname: string): string {
        const dot = qname.indexOf('.');
        const ctx = qname.slice(0, dot);
        const name = qname.slice(dot + 1);
        if (ctx === this.ctx) return name;
        this.imports.add(ctx);
        return `${ctx}.${name}`;
    }

    /** Emits a JSDoc block (single line when short); nothing for an empty list. */
    private jsdoc(lines: string[]): void {
        const all = lines.flatMap((l) => comment(l).split('\n'));
        if (all.length === 0) return;
        if (all.length === 1) this.out.push(`/** ${all[0]} */`);
        else this.out.push('/**', ...all.map((l) => ` * ${l}`.trimEnd()), ' */');
    }

    private line(text: string): void {
        this.out.push(text);
    }
}
